package com.aadil.ecommerce.entities;import com.aadil.ecommerce.enums.AdminRequestStatus;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;@Entity@Table (name = "AdminInvitation")@Datapublic class AdminInvitationEntity {    @GeneratedValue (strategy = GenerationType.IDENTITY)    @Id    private Long id;    @ManyToOne(fetch = FetchType.LAZY,optional = false)    @JoinColumn(name = "user_ID",nullable = false)    private UserEntity user;    @Column (nullable = false,updatable = false)    private String tokenHash;    @Column(nullable = false)    @Enumerated(EnumType.STRING)    private AdminRequestStatus adminRequestStatus;    @Column (nullable = false)    private LocalDateTime expiresAt;    @Column (nullable = false)    private LocalDateTime createdAt;    @PrePersist    protected void onCreate (){        this.createdAt = LocalDateTime.now();    }}